public sealed record Basket(ImmutableArray<Item> Items, decimal Total) {
    public Basket With(Item item) =>                       // copy + change, off to the side
        this with { Items = Items.Add(item), Total = Total + item.Price };
}
private Basket _basket = new(ImmutableArray<Item>.Empty, 0m);
_basket = _basket.With(item);   // publish: one reference store, no half-updated state

