public State Snapshot => Volatile.Read(ref _state);
public void Update(Func<State, State> change) {
    while (true) {                                  // build a complete replacement
        State current = Volatile.Read(ref _state);
        State next = change(current);
        if (ReferenceEquals(Interlocked.CompareExchange(ref _state, next, current), current))
